import{_ as a,o as n,c as r,j as e,a as d}from"./chunks/framework.Bd7kzaCy.js";const m=JSON.parse('{"title":"D.21　法律、授权、程序与责任","description":"","frontmatter":{"title":"D.21　法律、授权、程序与责任"},"headers":[],"relativePath":"theory/appendix-d/d-21.md","filePath":"theory/appendix-d/d-21.md"}'),l={name:"theory/appendix-d/d-21.md"};function o(s,t,p,i,c,u){return n(),r("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-21",tabindex:"-1"},[d("D.21　法律、授权、程序与责任 "),e("a",{class:"header-anchor",href:"#section-d-21","aria-label":'Permalink to "D.21　法律、授权、程序与责任 {#section-d-21}"'},"​")]),e("p",null,"正文连接：§5.5.5、5.5.7；§11.3；§13.5；§14；§15.2。研究入口：21.01—21.08。"),e("p",null,"法源有效、个案适用、道德理由、实际权限、救济程序及生活中的兑现分开。自然法、实证法、法律现实主义、宪政和法律多元研究，分别帮助分析这些问题。制度文本存在不证明执行，同一条规则的法律身份也不自动决定其规范评价。"),e("p",null,"同意、授权、代理、代表和诉权不同。某些公共或法定程序不以逐人私人委托为基础，不能因此被误写成当事人已同意；个人同意也不能替代机构所需的公共权限。模型推荐、现实执行和事后确认须分开记录，观察无权行为不应删去事实。"),e("p",null,"听取意见、尊重程序、证据纠正、改变决定、赔付及规则改写可能在不同时间发生。个案救济不证明制度已全面改正，未改判也不当然证明未听取。处罚、预防、补偿、真相、非暴力共处和宽恕不同，不能互相抵销；T0禁止强迫和解，不等于否定全部依法取证。"),e("p",null,"教学例：年度收入真实，却不足以确定每个短期给付窗口的收入。算术无误不能弥补法律上关键的时间信息缺口；补证责任、缺席默认与执行暂停需要具体规则。组织条件能解释伤害而不自动免除个人责任，个人错误也不能删除上游设计、资源与管理的作用。"),e("p",null,"复合程序中的权限能够依法接续，单项权限仍须在其适用节点有效。分别核验不得被解释为程序彼此永不相连，也不得凭几个无效片段拼出有效授权。解释、源数据更正、通知、改决定、赔偿及本人自由受领是不同终点；原记录可靠而时间转换错误时，应修正实际出错的推断与派生决定，不必删除全部可靠资料。"),e("p",null,"专题定位：21.01 自然法、实证法与法律现实主义；21.02 宪政、分权与制度制衡；21.03 权利、授权、同意与代表；21.04 程序正义、证据与申诉；21.05 刑罚、预防、修复与转型正义；21.06 责任归属与组织性伤害；21.07 法律多元、习惯法与跨国规则；21.08 算法决定、数字权利与可申诉性。")],-1)])])}const f=a(l,[["render",o]]);export{m as __pageData,f as default};
